WITH web_events_by_session AS (SELECT session_id, SUM(duration_sec) AS total_duration_sec FROM web_events WHERE page IN ('/search', '/cart', '/home') GROUP BY session_id) SELECT s.id, s.device, s.browser, webs.total_duration_sec FROM sessions s INNER JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.total_duration_sec > 1700 ORDER BY webs.total_duration_sec DESC;
